def doctor_report() -> dict[str, Any]:
    tools: dict[str, Any] = {}
    for key, (command, expected) in EXPECTED.items():
        path = resolve_executable(command)
        if not path:
            tools[key] = {"status": "missing", "command": command, "expected": expected}
            continue
        args = ["--version"]
        if command.endswith("langserver"):
            args = ["--version"]
        tool_env = os.environ.copy()
        if key == "csharp":
            dotnet_path = resolve_executable("dotnet")
            if dotnet_path:
                tool_env["DOTNET_ROOT"] = str(Path(dotnet_path).resolve().parent)
                tool_env.update({"DOTNET_NOLOGO": "1", "DOTNET_SKIP_FIRST_TIME_EXPERIENCE": "1", "DOTNET_CLI_TELEMETRY_OPTOUT": "1"})
        completed = run([path, *args], env=tool_env, timeout=30)
        output = (completed.stdout or completed.stderr).strip().splitlines()
        joined_output = "\n".join(output)
        tools[key] = {
            "status": "ready" if completed.returncode == 0 and _version_matches(expected, joined_output) else ("incompatible" if completed.returncode == 0 else "broken"),
            "command": command,
            "path": path,
            "version": output[0] if output else None,
            "expected": expected,
            "exit_status": completed.returncode,
        }
    python_completed = run([sys.executable, "--version"], timeout=20)
    python_lines = (python_completed.stdout or python_completed.stderr).strip().splitlines()
    python_version = python_lines[0] if python_lines else None
    python_tool = {
        "status": "ready" if python_completed.returncode == 0 and "3.14.6" in (python_version or "") else ("incompatible" if python_completed.returncode == 0 else "broken"),
        "command": "python",
        "path": str(Path(sys.executable).resolve()),
        "version": python_version,
        "expected": "3.14.6",
        "exit_status": python_completed.returncode,
    }
    node_path = resolve_executable("node")
    if node_path:
        node_completed = run([node_path, "--version"], timeout=20)
        node_lines = (node_completed.stdout or node_completed.stderr).strip().splitlines()
        node_version = node_lines[0] if node_lines else None
        node_tool = {
            "status": "ready" if node_completed.returncode == 0 and "24.19.0" in (node_version or "") else ("incompatible" if node_completed.returncode == 0 else "broken"),
            "command": "node",
            "path": str(Path(node_path).resolve()),
            "version": node_version,
            "expected": "24.19.0",
            "exit_status": node_completed.returncode,
        }
    else:
        node_tool = {"status": "missing", "command": "node", "expected": "24.19.0"}
    git_tool = command_version("git")
    tls_command = resolve_executable("typescript-language-server")
    compiler_candidates: list[Path] = []
    explicit_compiler = os.environ.get("CKB_TYPESCRIPT_PACKAGE_JSON")
    if explicit_compiler:
        compiler_candidates.append(Path(explicit_compiler).expanduser())
    if tls_command:
        compiler_candidates.append(Path(tls_command).resolve().parent.parent / "typescript" / "package.json")
    compiler_package = next((path for path in compiler_candidates if path.is_file()), None)
    compiler_version = None
    if compiler_package:
        try:
            compiler_version = json.loads(compiler_package.read_text(encoding="utf-8"))["version"]
        except Exception:
            compiler_version = None
    typescript_tool = {
        "status": "ready" if compiler_version == "7.0.2" else ("incompatible" if compiler_version else "missing"),
        "version": compiler_version,
        "expected": "7.0.2",
        "package_json": str(compiler_package.resolve()) if compiler_package else None,
    }
    explicit_tsserver = os.environ.get("CKB_TYPESCRIPT_TSSERVER_PATH")
    tsserver_candidates: list[Path] = []
    if explicit_tsserver:
        tsserver_candidates.append(Path(explicit_tsserver).expanduser())
    if tls_command:
        command_path = Path(tls_command).resolve()
        tsserver_candidates.extend(
            [
                command_path.parent.parent / "typescript" / "lib" / "tsserver.js",
                command_path.parent / "tsserver" / "node_modules" / "typescript" / "lib" / "tsserver.js",
            ]
        )
    tsserver_path = next((path.resolve() for path in tsserver_candidates if path.is_file()), None)
    tsserver_package = tsserver_path.parent.parent / "package.json" if tsserver_path and tsserver_path.is_file() else None
    tsserver_version = None
    if tsserver_package and tsserver_package.is_file():
        try:
            tsserver_version = json.loads(tsserver_package.read_text(encoding="utf-8"))["version"]
        except Exception:
            tsserver_version = None
    tsserver_tool = {
        "status": "ready" if tsserver_version == "6.0.3" else ("incompatible" if tsserver_version else "missing"),
        "version": tsserver_version,
        "expected": "6.0.3",
        "path": str(tsserver_path) if tsserver_path else None,
    }
    try:
        import tree_sitter

        ts_version = importlib.metadata.version("tree-sitter")
        expected_grammars = {
            "tree_sitter_c": ("tree-sitter-c", "0.24.2"),
            "tree_sitter_cpp": ("tree-sitter-cpp", "0.23.4"),
            "tree_sitter_javascript": ("tree-sitter-javascript", "0.25.0"),
            "tree_sitter_python": ("tree-sitter-python", "0.25.0"),
            "tree_sitter_c_sharp": ("tree-sitter-c-sharp", "0.23.5"),
        }
        grammars = {}
        for module, (distribution, expected_version) in expected_grammars.items():
            try:
                __import__(module)
                actual_version = importlib.metadata.version(distribution)
                grammars[module] = {"status": "ready" if actual_version == expected_version else "incompatible", "version": actual_version, "expected": expected_version}
            except Exception as exc:
                grammars[module] = {"status": "missing", "detail": str(exc), "expected": expected_version}
        tree_sitter_status = {
            "status": "ready" if ts_version == "0.26.0" and all(v["status"] == "ready" for v in grammars.values()) else "incompatible",
            "version": ts_version,
            "expected": "0.26.0",
            "grammars": grammars,
        }
    except Exception as exc:
        tree_sitter_status = {"status": "missing", "detail": str(exc)}
    try:
        from .graphify_core import GRAPHIFY_COMMIT, GRAPHIFY_VERSION, _networkx_modules

        nx, cluster, _labels, _scores = _networkx_modules()
        graphify_probe = nx.Graph()
        graphify_probe.add_edges_from([("source", "entity"), ("entity", "target")])
        graphify_partition = cluster(graphify_probe)
        graphify_status = {
            "status": "ready" if sorted(node for members in graphify_partition.values() for node in members) == ["entity", "source", "target"] else "incompatible",
            "version": GRAPHIFY_VERSION,
            "source_commit": GRAPHIFY_COMMIT,
            "networkx_version": nx.__version__,
            "mode": "vendored-community-projection",
        }
    except Exception as exc:
        graphify_status = {"status": "missing", "detail": str(exc)}
    try:
        probe = sqlite3.connect(":memory:")
        probe.execute("CREATE VIRTUAL TABLE fts_probe USING fts5(value, tokenize='trigram')")
        probe.execute("INSERT INTO fts_probe(value) VALUES('代码知识索引')")
        matched = probe.execute("SELECT count(*) FROM fts_probe WHERE fts_probe MATCH '代码知'").fetchone()[0]
        probe.close()
        agent_index_status = {
            "status": "ready" if matched == 1 else "incompatible",
            "sqlite_version": sqlite3.sqlite_version,
            "features": ["fts5", "trigram"],
        }
    except Exception as exc:
        agent_index_status = {"status": "missing", "detail": str(exc), "features": ["fts5", "trigram"]}
    tools.update({"python": python_tool, "node": node_tool, "git": git_tool, "tree_sitter": tree_sitter_status, "typescript": typescript_tool, "typescript_tsserver": tsserver_tool, "graphify_core": graphify_status, "agent_index": agent_index_status})
    required_scan = ["git", "tree_sitter", "python", "node", "javascript", "typescript", "typescript_tsserver", "c", "cpp", "csharp", "dotnet", "logseq", "graphify_core", "agent_index"]
    return {
        "schema_version": 2,
        "checked_at_utc": utc_now(),
        "status": "ready" if all(tools[name]["status"] == "ready" for name in required_scan) else "missing",
        "tools": tools,
        "private_runtime_root": str(private_runtime_root()),
    }

"""Deterministic query terms for identifiers and Chinese prose."""

from __future__ import annotations

import re
import unicodedata


MAX_QUERY_TERMS = 64
DEFAULT_FTS_TERM_LIMIT = 16

# These fixed query-glue characters are not a segmentation dictionary.  They
# only prevent sliding grams from crossing common grammatical boundaries.  The
# complete CJK run is retained, so negation and exact short phrases remain
# available without promoting fragments such as ``包不满`` or ``回的检``.
_CJK_QUERY_GLUE = frozenset("的了和与及或并而在把被将向从到为对时是会否不")
_CODE_RUN = re.compile(r"[A-Za-z0-9_.$:/\\#+-]+")
_CODE_SEPARATOR = re.compile(r"[._$:/\\#+-]+")
_CJK_RUN = re.compile(r"[\u3400-\u9fff]+")
_CJK_GLUE_RUN = re.compile("[" + "".join(sorted(_CJK_QUERY_GLUE)) + "]+")


def _split_camel(value: str) -> list[str]:
    return [
        part
        for part in re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", value).replace("::", " ").split()
        if part
    ]


def _ranked_terms(text: str) -> list[str]:
    normalized = unicodedata.normalize("NFKC", text)
    priorities: dict[str, int] = {}

    def add(value: str, priority: int) -> None:
        if value:
            priorities[value] = min(priorities.get(value, priority), priority)

    for run in _CODE_RUN.findall(normalized):
        lowered = run.casefold().strip("._$:/\\#+-")
        if len(lowered) >= 2:
            add(lowered, 0)
        for part in _CODE_SEPARATOR.split(run):
            if len(part) >= 2:
                add(part.casefold(), 1)
            for camel in _split_camel(part):
                if len(camel) >= 2:
                    add(camel.casefold(), 1)

    for run in _CJK_RUN.findall(normalized):
        # Preserve the complete phrase, including a single explicit Han
        # character.  FTS filtering separately requires at least three code
        # points because every CKB FTS table uses the trigram tokenizer.
        add(run, 0)
        for span in (value for value in _CJK_GLUE_RUN.split(run) if value):
            if len(span) >= 2:
                add(span, 1)
            for width, priority in ((3, 2), (2, 3)):
                for index in range(max(0, len(span) - width + 1)):
                    add(span[index : index + width], priority)

    return sorted(priorities, key=lambda value: (priorities[value], -len(value), value))


def search_terms(text: str, limit: int = MAX_QUERY_TERMS) -> list[str]:
    """Return bounded query terms in fixed signal, length, and lexical order."""
    if limit < 0:
        raise ValueError("query term limit must be non-negative")
    return _ranked_terms(text)[:limit]


def index_terms(text: str) -> list[str]:
    """Return the same deterministic terms without the query-side cap."""
    return _ranked_terms(text)


def fts_query_terms(text: str, limit: int = DEFAULT_FTS_TERM_LIMIT) -> list[str]:
    """Select trigram-compatible terms from the bounded query ordering."""
    if limit < 0:
        raise ValueError("FTS term limit must be non-negative")
    return [term for term in search_terms(text) if len(term) >= 3][:limit]


def build_fts_query(text: str, limit: int = DEFAULT_FTS_TERM_LIMIT) -> str | None:
    values = fts_query_terms(text, limit)
    if not values:
        return None
    return " OR ".join('"' + value.replace('"', '""') + '"' for value in values)


def explicit_anchors(text: str) -> list[str]:
    """Retain explicit code anchors independently from prose term ranking."""
    normalized = unicodedata.normalize("NFKC", text)
    anchors: set[str] = set()
    for value in re.findall(
        r"[A-Za-z_][A-Za-z0-9_]*(?:(?:::|[./#$:-])[A-Za-z0-9_]+)+|[A-Za-z_][A-Za-z0-9_]{2,}",
        normalized,
    ):
        if (
            any(character.isupper() for character in value[1:])
            or any(character in value for character in "_./#$:-")
            or any(character.isdigit() for character in value)
        ):
            anchors.add(value.casefold())
    return sorted(anchors)

def search_terms(text: str, limit: int = MAX_QUERY_TERMS) -> list[str]:
    """Return bounded query terms in fixed signal, length, and lexical order."""
    if limit < 0:
        raise ValueError("query term limit must be non-negative")
    return _ranked_terms(text)[:limit]

def audit_references(output: Path) -> dict[str, Any]:
    output = _validate_output(output)
    root = _root(output)
    manifests = _manifests(output)
    errors: list[dict[str, Any]] = []
    pending = 0
    superseded = 0
    for manifest in manifests:
        reference_id = str(manifest.get("reference_id") or "")
        source = Path(str(manifest.get("source_file") or ""))
        if not source.is_file():
            errors.append({"reason": "reference-source-missing", "reference_id": reference_id})
            continue
        if sha256_file(source) != manifest.get("source_sha256"):
            errors.append({"reason": "reference-source-drift", "reference_id": reference_id})
        try:
            _validate_license(str(manifest.get("license") or ""))
            _decode_source(source)
        except CkbError as exc:
            errors.append({"reason": "reference-source-invalid", "reference_id": reference_id, "detail": str(exc)})
        status = manifest.get("status")
        if status == "pending-agent-review":
            pending += 1
        elif status == "superseded":
            superseded += 1
        elif status == "agent-reviewed":
            review = Path(str(manifest.get("review_file") or ""))
            try:
                if not review.is_file():
                    raise CkbError("review file is missing")
                _validate_review(manifest, json_load(review))
            except CkbError as exc:
                errors.append({"reason": "reference-review-invalid", "reference_id": reference_id, "detail": str(exc)})
        else:
            errors.append({"reason": "reference-status-invalid", "reference_id": reference_id, "status": status})
    active = _active_reviewed(manifests)
    projection_path = root / "projection.json"
    projection = json_load(projection_path) if projection_path.is_file() else {"pages": [], "files": []}
    expected_ids = {item["reference_id"] for item in active}
    actual_ids = {item["reference_id"] for item in projection.get("pages", [])}
    if actual_ids != expected_ids:
        errors.append({"reason": "reference-projection-set", "missing": sorted(expected_ids - actual_ids), "extra": sorted(actual_ids - expected_ids)})
    if int(projection.get("page_count", 0)) != len(active) or int(projection.get("page_limit_per_source", 1)) != 1:
        errors.append({"reason": "reference-page-quota", "active": len(active), "projection": projection.get("page_count")})
    for item in projection.get("pages", []):
        relative = str(item["file"])
        left = output / "markdown" / relative
        right = output / "human" / relative
        if not left.is_file() or not right.is_file() or left.read_bytes() != right.read_bytes():
            errors.append({"reason": "reference-page-mirror", "path": relative})
        elif not contains_chinese_narrative(left.read_text(encoding="utf-8")) or LONG_HEX.search(left.read_text(encoding="utf-8")):
            errors.append({"reason": "reference-page-human-contract", "path": relative})
    left_index = output / "markdown" / REFERENCE_INDEX
    right_index = output / "human" / REFERENCE_INDEX
    if active and (not left_index.is_file() or not right_index.is_file() or left_index.read_bytes() != right_index.read_bytes()):
        errors.append({"reason": "reference-index-mirror"})
    machine = output / "machine/knowledge.sqlite"
    machine_counts = {"sources": 0, "documents": 0}
    if machine.is_file():
        import sqlite3

        connection = sqlite3.connect(f"file:{machine.as_posix()}?mode=ro", uri=True)
        try:
            tables = {row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if "reference_sources" in tables:
                machine_counts["sources"] = connection.execute("SELECT count(*) FROM reference_sources").fetchone()[0]
                machine_counts["documents"] = connection.execute("SELECT count(*) FROM documents WHERE kind='reference'").fetchone()[0]
            elif manifests and pending == 0:
                errors.append({"reason": "reference-machine-table-missing"})
        finally:
            connection.close()
        if pending == 0 and (machine_counts["sources"] != len(manifests) or machine_counts["documents"] != len(active)):
            errors.append({"reason": "reference-machine-count", "actual": machine_counts, "expected": {"sources": len(manifests), "documents": len(active)}})
    elif manifests:
        errors.append({"reason": "reference-machine-missing"})
    status = "failed" if errors else "pending-agent-review" if pending else "passed"
    result = {
        "schema_version": REFERENCE_SCHEMA_VERSION,
        "status": status,
        "counts": {"total": len(manifests), "active": len(active), "pending": pending, "superseded": superseded},
        "page_count": len(projection.get("pages", [])),
        "page_limit_per_source": 1,
        "machine_counts": machine_counts,
        "errors": errors,
    }
    root.mkdir(parents=True, exist_ok=True)
    json_write(root / "audit.json", result)
    _set_marker(output, status, {"audit": str((root / "audit.json").resolve()), "counts": result["counts"], "errors": errors})
    return result
